1	package dashboard
2	
3	import (
4		"encoding/json"
5		"net/http"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10	
11		"github.com/integrio-intropy/intropy-cli/internal/template"
12	)
13	
14	// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
15	// the detail endpoint returns, so a huge file cannot bloat a response.
16	const maxDocBytes = 128 * 1024
17	
18	// apiServer holds the request-independent state for the JSON API.
19	type apiServer struct {
20		root    string
21		version string
22	}
23	
24	// fileDoc is a text document surfaced in an integration's detail view.
25	type fileDoc struct {
26		Name    string `json:"name"`
27		Content string `json:"content"`
28	}
29	
30	// integrationSummary is a scaffold entry plus the coordinates the sidebar
31	// tree groups by: Name is the directory that carries the .intropy record,
32	// System is that directory's parent and Domain the system's parent. System
33	// is empty when the integration sits directly under the workspace root, and
34	// Domain is empty when the system does.
35	type integrationSummary struct {
36		template.ScaffoldEntry
37		Name   string `json:"name"`
38		System string `json:"system,omitempty"`
39		Domain string `json:"domain,omitempty"`
40	}
41	
42	// integrationDetail is a single integration plus best-effort, on-disk
43	// enrichment. Every enrichment field is optional and absent when the
44	// corresponding file or directory does not exist.
45	type integrationDetail struct {
46		integrationSummary
47		Agents        *fileDoc        `json:"agents,omitempty"`
48		Readme        *fileDoc        `json:"readme,omitempty"`
49		Components    []DaprComponent `json:"components,omitempty"`
50		PipelineSteps []string        `json:"pipelineSteps,omitempty"`
51	}
52	
53	// newHandler wires the API routes and the SPA static handler onto a mux.
54	func newHandler(root, version string) (http.Handler, error) {
55		api := &apiServer{root: root, version: version}
56		static, err := staticHandler()
57		if err != nil {
58			return nil, err
59		}
60	
61		mux := http.NewServeMux()
62		mux.HandleFunc("GET /api/health", api.health)
63		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
64		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
65		mux.HandleFunc("GET /api/flow", api.flow)
66		mux.Handle("/", static)
67		return mux, nil
68	}
69	
70	func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
71		writeJSON(w, http.StatusOK, map[string]string{
72			"status":  "ok",
73			"version": s.version,
74		})
75	}
76	
77	// listIntegrations mirrors `int list -o json` — the same scaffold entries in
78	// the same order — with the derived name/system fields added on top and each
79	// Path normalized to a root-relative identifier. The response is always an
80	// array (never null) even when empty.
81	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
82		entries, _ := template.ListScaffolds(s.root)
83		summaries := make([]integrationSummary, 0, len(entries))
84		for _, e := range entries {
85			summaries = append(summaries, s.summarize(e))
86		}
87		writeJSON(w, http.StatusOK, summaries)
88	}
89	
90	// summarize derives an entry's tree coordinates from its path. The workspace
91	// root itself never counts as a system or domain, so an integration
92	// scaffolded at the root has neither and one directly under the root has a
93	// system but no domain. The served Path is made root-relative so it is a
94	// stable, URL-safe identifier regardless of whether run was given a relative
95	// or absolute root (an absolute path would otherwise break detail lookups).
96	func (s *apiServer) summarize(e template.ScaffoldEntry) integrationSummary {
97		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
98		sum.Path = s.relPath(e.Path)
99		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
100		parent := filepath.Dir(path)
101		if path == root || parent == root {
102			return sum
103		}
104		sum.System = filepath.Base(parent)
105		if grand := filepath.Dir(parent); grand != root {
106			sum.Domain = filepath.Base(grand)
107		}
108		return sum
109	}
110	
111	// relPath turns an entry's on-disk path into the root-relative, slash-separated
112	// identifier used in API responses and URLs. It falls back to the cleaned path
113	// so a value is always produced even if Rel fails (e.g. differing volumes).
114	func (s *apiServer) relPath(p string) string {
115		if rel, err := filepath.Rel(s.root, p); err == nil {
116			return filepath.ToSlash(rel)
117		}
118		return filepath.ToSlash(filepath.Clean(p))
119	}
120	
121	// flow returns every integration enriched with the pipeline steps and Dapr
122	// components the flow canvas draws, so the whole graph loads in one request.
123	// It reuses integrationDetail but leaves the document fields (agents/readme)
124	// nil — the canvas nodes do not render them.
125	func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
126		entries, _ := template.ListScaffolds(s.root)
127		nodes := make([]integrationDetail, 0, len(entries))
128		for _, e := range entries {
129			dir := e.Path
130			nodes = append(nodes, integrationDetail{
131				integrationSummary: s.summarize(e),
132				Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
133				PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
134			})
135		}
136		writeJSON(w, http.StatusOK, nodes)
137	}
138	
139	func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
140		want := strings.Trim(r.PathValue("path"), "/")
141		entries, _ := template.ListScaffolds(s.root)
142		for _, e := range entries {
143			if s.relPath(e.Path) == want {
144				writeJSON(w, http.StatusOK, s.enrich(e))
145				return
146			}
147		}
148		writeError(w, http.StatusNotFound, "integration not found: "+want)
149	}
150	
151	// enrich reads optional on-disk context for an integration. The entry's Path
152	// is already usable from the process working directory (see ListScaffolds), so
153	// it doubles as the project directory.
154	func (s *apiServer) enrich(e template.ScaffoldEntry) integrationDetail {
155		dir := e.Path
156		return integrationDetail{
157			integrationSummary: s.summarize(e),
158			Agents:             readDoc(dir, "AGENTS.md"),
159			Readme:             readDoc(dir, "README.md"),
160			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
161			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
162		}
163	}
164	
165	// readDoc returns the named text file's (possibly truncated) contents, or nil
166	// if it is absent or unreadable.
167	func readDoc(dir, name string) *fileDoc {
168		data, err := os.ReadFile(filepath.Join(dir, name))
169		if err != nil {
170			return nil
171		}
172		if len(data) > maxDocBytes {
173			data = data[:maxDocBytes]
174		}
175		return &fileDoc{Name: name, Content: string(data)}
176	}
177	
178	// listNames returns the sorted base names of the files directly under dir, or
179	// nil if dir is absent or unreadable.
180	func listNames(dir string) []string {
181		ents, err := os.ReadDir(dir)
182		if err != nil {
183			return nil
184		}
185		var names []string
186		for _, ent := range ents {
187			if !ent.IsDir() {
188				names = append(names, ent.Name())
189			}
190		}
191		sort.Strings(names)
192		return names
193	}
194	
195	func writeJSON(w http.ResponseWriter, status int, v any) {
196		w.Header().Set("Content-Type", "application/json; charset=utf-8")
197		w.WriteHeader(status)
198		enc := json.NewEncoder(w)
199		enc.SetIndent("", "  ")
200		_ = enc.Encode(v)
201	}
202	
203	func writeError(w http.ResponseWriter, status int, msg string) {
204		writeJSON(w, status, map[string]string{"error": msg})
205	}
206

