13	func writeScaffold(t *testing.T, dir, tmpl, version string) {
14		t.Helper()
15		intropyDir := filepath.Join(dir, ".intropy")
16		if err := os.MkdirAll(intropyDir, 0o755); err != nil {
17			t.Fatal(err)
18		}
19		body := `{"schemaVersion":1,"template":"` + tmpl + `","owner":"integrio-intropy","repo":"intropy-templates","version":"` + version + `","dataFlow":"both","values":{"appId":"int1"}}` + "\n"
20		if err := os.WriteFile(filepath.Join(intropyDir, "scaffold.json"), []byte(body), 0o644); err != nil {
21			t.Fatal(err)
22		}
23	}
24	
25	func testHandler(t *testing.T, root string) http.Handler {
26		t.Helper()
27		h, err := newHandler(root, "test")
28		if err != nil {
29			t.Fatalf("newHandler: %v", err)
30		}
31		return h
32	}
33	
34	func get(t *testing.T, h http.Handler, path string) *httptest.ResponseRecorder {
35		t.Helper()
36		rec := httptest.NewRecorder()
37		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, path, nil))
38		return rec
39	}
