41	func TestHealth(t *testing.T) {
42		rec := get(t, testHandler(t, t.TempDir()), "/api/health")
43		if rec.Code != http.StatusOK {
44			t.Fatalf("status = %d, want 200", rec.Code)
45		}
46		var body map[string]string
47		if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
48			t.Fatalf("body not JSON: %v", err)
49		}
50		if body["status"] != "ok" || body["version"] != "test" {
51			t.Errorf("unexpected health body: %v", body)
52		}
