80	
81	// TestIntegrationsTreeFields checks the derived sidebar-tree coordinates:
82	// the integration is named after the directory carrying .intropy, its system
83	// is the parent directory and its domain the system's parent. System and
84	// domain are absent when the respective level would be the workspace root.
85	func TestIntegrationsTreeFields(t *testing.T) {
86		tmp := t.TempDir()
87		t.Chdir(tmp)
88		writeScaffold(t, filepath.Join(tmp, "sales", "erp", "order-intake"), "hello-world", "v0.1.6")
89		writeScaffold(t, filepath.Join(tmp, "sales", "erp", "invoice-export"), "hello-world", "v0.1.6")
90		writeScaffold(t, filepath.Join(tmp, "erp", "stock-sync"), "hello-world", "v0.1.6")
91		writeScaffold(t, filepath.Join(tmp, "standalone"), "hello-world", "v0.1.6")
92	
93		rec := get(t, testHandler(t, "."), "/api/integrations")
94		var entries []map[string]any
95		if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
96			t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
97		}
98		if len(entries) != 4 {
99			t.Fatalf("entries = %d, want 4", len(entries))
100		}
101	
102		type coords struct{ system, domain string }
103		got := map[string]coords{}
104		for _, e := range entries {
105			name, _ := e["name"].(string)
106			system, _ := e["system"].(string)
107			domain, _ := e["domain"].(string)
108			got[name] = coords{system, domain}
109		}
110		want := map[string]coords{
111			"order-intake":   {"erp", "sales"},
112			"invoice-export": {"erp", "sales"},
113			"stock-sync":     {"erp", ""},
114			"standalone":     {"", ""},
115		}
116		for name, w := range want {
117			g, ok := got[name]
118			if !ok {
119				t.Errorf("missing entry named %q, got %v", name, got)
120				continue
121			}
122			if g != w {
123				t.Errorf("coords for %q = %+v, want %+v", name, g, w)
124			}
125		}
126	}
