157	// TestFlowComponents checks that /api/flow parses the integration's Dapr
158	// component YAML into structured, classified components (not filenames).
159	func TestFlowComponents(t *testing.T) {
160		tmp := t.TempDir()
161		t.Chdir(tmp)
162		proj := filepath.Join(tmp, "sales", "orders")
163		writeScaffold(t, proj, "hello-world", "v0.1.6")
164		comps := filepath.Join(proj, "local", "dapr-components")
165		if err := os.MkdirAll(comps, 0o755); err != nil {
