170			t.Fatal(err)
171		}
172		if err := os.WriteFile(filepath.Join(comps, "orders-in.yaml"),
173			[]byte("metadata:\n  name: orders-in\nspec:\n  type: bindings.localstorage\n  metadata:\n    - name: direction\n      value: input\n"), 0o644); err != nil {
174			t.Fatal(err)
175		}
176	
177		rec := get(t, testHandler(t, "."), "/api/flow")
178		var nodes []struct {
179			Name       string          `json:"name"`
180			System     string          `json:"system"`
181			DataFlow   string          `json:"dataFlow"`
182			Components []DaprComponent `json:"components"`
183		}
184		if err := json.Unmarshal(rec.Body.Bytes(), &nodes); err != nil {
185			t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
186		}
187		if len(nodes) != 1 {
188			t.Fatalf("nodes = %d, want 1", len(nodes))
189		}
190		if nodes[0].System != "sales" {
191			t.Errorf("system = %q, want sales", nodes[0].System)
192		}
193		// The scaffold record's dataFlow flows through the embedded Scaffold.
194		if nodes[0].DataFlow != "both" {
195			t.Errorf("dataFlow = %q, want both", nodes[0].DataFlow)
196		}
197		if len(nodes[0].Components) != 2 {
198			t.Fatalf("components = %d, want 2: %+v", len(nodes[0].Components), nodes[0].Components)
