// refName extracts the display name from an entity ref: "component:pim-extractor"
// → "pim-extractor", "system:default/pim" → "pim".
function refName(ref: string): string {
  const rest = ref.slice(ref.indexOf(':') + 1)
  const slash = rest.lastIndexOf('/')
  return slash >= 0 ? rest.slice(slash + 1) : rest
}

// buildDeclaredGraph renders a system's declared topology: components and
// topics laid out left-to-right by flow depth inside the boundary, external
// systems (via connectors) and used services outside it. Unlike buildGraph
// nothing here is inferred — every node and edge is declared by the record.
function buildDeclaredGraph(
  topo: Topology,
  items: IntegrationDetail[],
): { nodes: Node[]; edges: Edge[] } {
  const comps = topo.components ?? []
  const resources = topo.resources ?? []
  const declaredEdges = topo.edges ?? []
  const topics = resources.filter((r) => r.type === 'topic')
  const connectors = new Map(
    resources.filter((r) => r.type === 'connector').map((r) => [`resource:${r.name}`, r]),
  )

  // Map component refs to integration paths (via `project`) so clicking a
  // declared node selects the scaffolded integration when one exists.
  const nodeId = new Map<string, string>()
  for (const c of comps) {
    const path =
      c.project && (topo.path === '.' ? c.project : `${topo.path}/${c.project}`)
    const matched = path && items.some((it) => it.path === path) ? path : undefined
    nodeId.set(`component:${c.name}`, matched ?? `component:${c.name}`)
  }
  for (const t of topics) nodeId.set(`resource:${t.name}`, `topic:${t.name}`)

  // Contract surfaces: an API's topic ref marks that topic as a contract.
  const apiOf = new Map<string, TopologyApi>()
  for (const a of topo.apis ?? []) apiOf.set(a.topic ?? `resource:${a.name}`, a)

  // Longest-path layering over the internal flow edges (publish, consume,
  // uses between declared entities) decides each node's column. Kahn-style
  // relaxation; anything left by a cycle lands in column 0 rather than
  // failing the render.
  const internal = new Set([
    ...comps.map((c) => `component:${c.name}`),
    ...topics.map((t) => `resource:${t.name}`),
  ])
  const succ = new Map<string, string[]>()
  const indeg = new Map<string, number>()
  for (const r of internal) {
    succ.set(r, [])
    indeg.set(r, 0)
  }
  for (const e of declaredEdges) {
    if (e.kind === 'connector') continue
    if (!internal.has(e.from) || !internal.has(e.to)) continue
    succ.get(e.from)?.push(e.to)
    indeg.set(e.to, (indeg.get(e.to) ?? 0) + 1)
  }
  const depth = new Map<string, number>()
  const queue = [...internal].filter((r) => indeg.get(r) === 0)
  for (const r of queue) depth.set(r, 0)
  while (queue.length > 0) {
    const r = queue.shift()!
    for (const n of succ.get(r) ?? []) {
      depth.set(n, Math.max(depth.get(n) ?? 0, (depth.get(r) ?? 0) + 1))
      indeg.set(n, indeg.get(n)! - 1)
      if (indeg.get(n) === 0) queue.push(n)
    }
  }
  for (const r of internal) if (!depth.has(r)) depth.set(r, 0)

  const cols = Math.max(1, Math.max(...[...depth.values()], 0) + 1)
  const contentTop = GROUP_HEADER
  const groupWidth = GROUP_PAD * 2 + cols * NODE_W + (cols - 1) * COL_GAP
  const colX = (d: number) => GROUP_PAD + d * (NODE_W + COL_GAP)

  const nodes: Node[] = []
  const edges: Edge[] = []
  const groupId = 'system'
  const rowsInCol: number[] = new Array<number>(cols).fill(0)
  const place = (d: number): { x: number; y: number; row: number } => {
    const row = rowsInCol[d]++
    return { x: colX(d), y: contentTop + row * (NODE_H + ROW_GAP), row }
  }

  for (const c of comps) {
    const ref = `component:${c.name}`
    const pos = place(depth.get(ref) ?? 0)
    nodes.push({
      id: nodeId.get(ref)!,
      type: 'integration',
      parentId: groupId,
      extent: 'parent',
      position: { x: pos.x, y: pos.y },
      data: {
        name: c.name,
        template: c.type,
        dataFlow: TEMPLATE_DATA_FLOW[c.type],
        trigger: c.trigger?.kind === 'schedule' ? c.trigger.schedule : undefined,
        selected: false,
      } satisfies IntNodeData,
    })
  }

  for (const t of topics) {
    const ref = `resource:${t.name}`
    const pos = place(depth.get(ref) ?? 0)
    const contract = apiOf.get(ref)
    nodes.push({
      id: nodeId.get(ref)!,
      type: 'topic',
      parentId: groupId,
      extent: 'parent',
      // Topics are narrower than component cards; center them in the column.
      position: { x: pos.x + (NODE_W - INFRA_W) / 2, y: pos.y },
      style: { width: INFRA_W, height: INFRA_H },
      data: {
        name: t.name,
        entity: t.entity,
        contract: contract?.contract,
      } satisfies TopicNodeData,
    })
  }

  const maxRows = Math.max(1, ...rowsInCol)
  const groupHeight = contentTop + maxRows * (NODE_H + ROW_GAP) - ROW_GAP + GROUP_PAD
  nodes.unshift({
    id: groupId,
    type: 'group',
    position: { x: 0, y: 0 },
    data: { title: topo.system.name, count: comps.length } satisfies GroupNodeData,
    style: { width: groupWidth, height: groupHeight },
    draggable: false,
    selectable: false,
  })

  // Externals: connectors resolve to the external system they front (left
  // when the connector feeds a component, right when a component feeds it);
  // `uses` targets outside the file become plain external service nodes.
  let srcIndex = 0
  let sinkIndex = 0
  const external = (id: string, data: ExtNodeData, isSource: boolean): void => {
    nodes.push({
      id,
      type: 'external',
      position: {
        x: isSource ? -(EXT_W + EXT_GAP) : groupWidth + EXT_GAP,
        y: contentTop + (isSource ? srcIndex++ : sinkIndex++) * (EXT_H + EXT_VGAP),
      },
      style: { width: EXT_W, height: EXT_H },
      data,
      draggable: true,
    })
  }

  declaredEdges.forEach((e, i) => {
    const id = `e:decl:${i}`
    if (e.kind === 'publish' || e.kind === 'consume') {
      const source = nodeId.get(e.from)
      const target = nodeId.get(e.to)
      if (!source || !target) return
      edges.push({
        id,
        source,
        sourceHandle: e.kind === 'publish' ? 'ext' : 'out',
        target,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
        ...(e.port && e.port !== 'default' && { label: e.port }),
      })
      return
    }
    if (e.kind === 'connector') {
      const isSource = connectors.has(e.from)
      const conn = connectors.get(isSource ? e.from : e.to)
      const comp = nodeId.get(isSource ? e.to : e.from)
      if (!conn || !comp) return
      const extId = `ext:${conn.name}`
      external(
        extId,
        {
          name: conn.externalSystem ? refName(conn.externalSystem) : conn.name,
          type: conn.transport ?? conn.daprComponent ?? 'connector',
          direction: isSource ? 'input' : undefined,
        },
        isSource,
      )
      edges.push({
        id,
        source: isSource ? extId : comp,
        sourceHandle: isSource ? 'out' : 'ext',
        target: isSource ? comp : extId,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
      return
    }
    if (e.kind === 'uses') {
      const source = nodeId.get(e.from)
      if (!source || internal.has(e.to)) return
      const extId = `ext:uses:${e.to}`
      if (!nodes.some((n) => n.id === extId)) {
        external(extId, { name: refName(e.to), type: e.to }, false)
      }
      edges.push({
        id,
        source,
        sourceHandle: 'ext',
        target: extId,
        targetHandle: 'in',
        className: 'rf-edge-infra',
      })
    }
  })

  return { nodes, edges }
}

