using System.Text.Json;
using Aggregator.Configuration;
using Aggregator.Processing;
using Dapr.Messaging.PublishSubscribe;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Shared.Extractor;

namespace Aggregator.Subscriber;

public sealed class AggregatorSubscriber(
    DaprPublishSubscribeClient client,
    AggregatorRunner runner,
    IOptions<AggregatorConfig> config,
    ILogger<AggregatorSubscriber> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

    public async Task RunOnceAsync(CancellationToken ct)
    {
        var input = config.Value.Input;
        var done = new TaskCompletionSource<TopicResponseAction>(TaskCreationOptions.RunContinuationsAsynchronously);
        var options = new DaprSubscriptionOptions(new MessageHandlingPolicy(
            TimeoutDuration: TimeSpan.FromHours(6),
            DefaultResponseAction: TopicResponseAction.Retry));

        logger.LogInformation("Subscribing to {PubSub}/{Topic}", input.PubSubName, input.Topic);

        await using var subscription = await client.SubscribeAsync(
            input.PubSubName,
            input.Topic,
            options,
            async (message, innerCt) =>
            {
                var action = await HandleAsync(message, innerCt);
                done.TrySetResult(action);
                return action;
            },
            ct);

        await using var _ = ct.Register(() => done.TrySetCanceled(ct));
        await done.Task;
    }

    private async Task<TopicResponseAction> HandleAsync(TopicMessage message, CancellationToken ct)
    {
        try
        {
            var export = JsonSerializer.Deserialize<ExportEvent>(message.Data.Span, JsonOptions);
            if (export is null)
            {
                logger.LogWarning("Discarding empty ExportEvent payload from message {MessageId}", message.Id);
                return TopicResponseAction.Drop;
            }

            await runner.RunAsync(export, ct);
            return TopicResponseAction.Success;
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            return TopicResponseAction.Retry;
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Failed to process ExportEvent {MessageId}", message.Id);
            return TopicResponseAction.Retry;
        }
    }
}
