using System.Text.Json;
using System.Threading.RateLimiting;
using Aggregator.Configuration;
using CloudNative.CloudEvents;
using CloudNative.CloudEvents.SystemTextJson;
using Dapr.Client;
using Grpc.Core;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace Aggregator.Processing;

public sealed class EventPublisher : IDisposable
{
    private static readonly JsonEventFormatter Formatter = new();
    private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);
    private static readonly Uri Source = new($"urn:{Constants.ComponentName}");

    private readonly DaprClient _dapr;
    private readonly AggregatorConfig _config;
    private readonly ILogger<EventPublisher> _logger;
    private readonly TokenBucketRateLimiter _limiter;

    public EventPublisher(DaprClient dapr, IOptions<AggregatorConfig> config, ILogger<EventPublisher> logger)
    {
        _dapr = dapr;
        _config = config.Value;
        _logger = logger;
        var p = _config.Publish;
        _limiter = new TokenBucketRateLimiter(new TokenBucketRateLimiterOptions
        {
            TokenLimit = p.RateLimitBurst,
            TokensPerPeriod = p.RateLimitPerSecond,
            ReplenishmentPeriod = TimeSpan.FromSeconds(1),
            QueueLimit = int.MaxValue,
            QueueProcessingOrder = QueueProcessingOrder.OldestFirst,
            AutoReplenishment = true,
        });
    }

    public async Task PublishAsync<T>(
        string topic,
        string type,
        string subject,
        T payload,
        CancellationToken ct)
    {
        var bytes = Encode(type, subject, payload);
        var p = _config.Publish;

        for (var attempt = 1; ; attempt++)
        {
            using var lease = await _limiter.AcquireAsync(1, ct);
            try
            {
                await _dapr.PublishByteEventAsync(
                    _config.Output.PubSubName,
                    topic,
                    bytes,
                    "application/cloudevents+json",
                    cancellationToken: ct);
                return;
            }
            catch (Exception ex) when (attempt < p.MaxAttempts && IsTransient(ex))
            {
                var delay = Backoff(p.BaseDelay, p.MaxDelay, attempt);
                _logger.LogWarning(ex,
                    "Publish to {Topic} failed (attempt {Attempt}/{Max}); retrying in {Delay}",
                    topic, attempt, p.MaxAttempts, delay);
                await Task.Delay(delay, ct);
            }
        }
    }

    private static bool IsTransient(Exception ex) => ex switch
    {
        RpcException rpc => rpc.StatusCode is StatusCode.Internal
                                            or StatusCode.Unavailable
                                            or StatusCode.ResourceExhausted
                                            or StatusCode.DeadlineExceeded,
        Dapr.DaprException when ex.InnerException is not null => IsTransient(ex.InnerException),
        _ => false,
    };

    private static TimeSpan Backoff(TimeSpan @base, TimeSpan max, int attempt)
    {
        var exp = Math.Min(max.TotalMilliseconds, @base.TotalMilliseconds * Math.Pow(2, attempt - 1));
        var jitter = Random.Shared.NextDouble() * 0.3 * exp;
        return TimeSpan.FromMilliseconds(exp + jitter);
    }

    private static ReadOnlyMemory<byte> Encode<T>(string type, string subject, T payload)
    {
        var cloudEvent = new CloudEvent
        {
            Id = Guid.NewGuid().ToString(),
            Type = type,
            Source = Source,
            Subject = subject,
            Time = DateTimeOffset.UtcNow,
            DataContentType = "application/json",
            Data = JsonSerializer.SerializeToElement(payload, JsonOptions),
        };
        return Formatter.EncodeStructuredModeMessage(cloudEvent, out _);
    }

    public void Dispose() => _limiter.Dispose();
}

