using CloudNative.CloudEvents;
using Intropy.Framework.Core.Pipeline.Abstractions.Results;
using Extractor.Perfion.Pipelines.Batch;
using Microsoft.Extensions.Logging;

namespace Extractor.Perfion.Batch;

public sealed class BatchRunner(
    BatchPipeline<BatchReceiver.ReceivedBatch, PerfionBatchContext> pipeline,
    ILogger<BatchRunner> logger)
{
    public async Task<int> RunAsync(CancellationToken ct)
    {
        var (result, ctx) = await pipeline.Execute(new PerfionBatchContext(), ct);

        return result switch
        {
            StepResult<CloudEvent>.Success => Done("completed", ctx, 0),
            StepResult<CloudEvent>.Cancelled => Done("cancelled (no batch ready or duplicate)", ctx, 0),
            StepResult<CloudEvent>.BusinessFailure bf => Fail($"business failure: {bf.Value.Description}", ctx, 1),
            StepResult<CloudEvent>.TechnicalFailure tf => Fail($"technical failure: {tf.Value.Description}", ctx, 1),
            StepResult<CloudEvent>.Aborted => Done("aborted", ctx, 130),
            _ => Fail($"unknown result: {result.GetType().Name}", ctx, 1),
        };
    }

    private int Done(string status, PerfionBatchContext ctx, int code)
    {
        logger.LogInformation("Batch run {Status} (exportId={ExportId})", status, ctx.Batch?.ExportId ?? "(none)");
        return code;
    }

    private int Fail(string status, PerfionBatchContext ctx, int code)
    {
        logger.LogError("Batch run {Status} (exportId={ExportId})", status, ctx.Batch?.ExportId ?? "(none)");
        return code;
    }
}
