public sealed class PerfionExportEventSerializeStep(
    IngestOptions options,
    ILogger<PerfionExportEventSerializeStep> logger)
    : BatchSerializeStep<BatchReceiver.ReceivedBatch, PerfionBatchContext>
{
    public override Task<(TechnicalStepResult<CloudEvent> Result, PerfionBatchContext Context)> ExecuteAsync(
        BatchReceiver.ReceivedBatch input, PerfionBatchContext context, CancellationToken ct)
    {
        var exportEvent = new ExportEvent
        {
