            Container = options.OutputContainerName,
            Files = context.ExportEventFiles,
        };

        var cloudEvent = new CloudEvent
        {
            Id = input.ExportId,
            Source = Constants.ExportEventSource,
            Type = Constants.ExportEventType,
            Subject = input.ExportId,
            Time = DateTimeOffset.UtcNow,
            DataContentType = "application/json",
            Data = exportEvent,
        };

        logger.LogDebug("Built CloudEvent {CloudEventId} for export {ExportId} with {FileCount} files",
            cloudEvent.Id, input.ExportId, context.ExportEventFiles.Count);

        return Task.FromResult<(TechnicalStepResult<CloudEvent>, PerfionBatchContext)>(
            (new TechnicalStepResult<CloudEvent>.Success(cloudEvent), context));
    }
