  // Externals sit outside the boundary, anchored to the component they touch
  // so edges stay short: a source connector directly left of its component,
  // and output connectors / used services dropped below the component's
  // column (stacked when several share one). This avoids the whole-diagram
  // crossings that a fixed left/right screen edge produces in a multi-column
  // pipeline.
  const belowCount = new Map<number, number>()
  const belowY = (col: number): number => {
    const n = belowCount.get(col) ?? 0
    belowCount.set(col, n + 1)
    return groupHeight + EXT_VGAP + n * (EXT_H + EXT_VGAP)
  }
  const pushExternal = (id: string, data: ExtNodeData, x: number, y: number): void => {
    if (nodes.some((n) => n.id === id)) return
    nodes.push({
      id,
      type: 'external',
      position: { x, y },
      style: { width: EXT_W, height: EXT_H },
      data,
      draggable: true,
    })
  }
  const centerUnder = (x: number) => x + (NODE_W - EXT_W) / 2

  declaredEdges.forEach((e, i) => {
    const id = `e:decl:${i}`
    if (e.kind === 'publish' || e.kind === 'consume') {
      const source = nodeId.get(e.from)
      const target = nodeId.get(e.to)
      if (!source || !target) return
      edges.push({
        id,
        source,
        sourceHandle: e.kind === 'publish' ? 'ext' : 'out',
        target,
        targetHandle: 'in',
        markerEnd: { type: MarkerType.ArrowClosed },
        className: 'rf-edge-ext',
      })
      return
    }
    if (e.kind === 'connector') {
      const isInput = connectors.has(e.from)
      const conn = connectors.get(isInput ? e.from : e.to)
      const compRef = isInput ? e.to : e.from
      const comp = nodeId.get(compRef)
      const anchor = compPos.get(compRef)
      if (!conn || !comp || !anchor) return
      const extId = `ext:${conn.name}`
      const data: ExtNodeData = {
        name: conn.externalSystem ? refName(conn.externalSystem) : conn.name,
        type: conn.transport ?? conn.daprComponent ?? 'connector',
        direction: isInput ? 'input' : undefined,
      }
      if (isInput) {
        pushExternal(extId, data, anchor.x - EXT_W - EXT_GAP, anchor.y)
        edges.push({
          id,
          source: extId,
          sourceHandle: 'out',
          target: comp,
          targetHandle: 'in',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      } else {
        pushExternal(extId, data, centerUnder(anchor.x), belowY(anchor.col))
        edges.push({
          id,
          source: comp,
          sourceHandle: 'infra',
          target: extId,
          targetHandle: 'top',
          markerEnd: { type: MarkerType.ArrowClosed },
          className: 'rf-edge-ext',
        })
      }
      return
    }
    if (e.kind === 'uses') {
      const comp = nodeId.get(e.from)
      const anchor = compPos.get(e.from)
      if (!comp || !anchor || internal.has(e.to)) return
      const extId = `ext:uses:${e.to}`
      pushExternal(extId, { name: refName(e.to), type: e.to }, centerUnder(anchor.x), belowY(anchor.col))
      edges.push({
        id,
        source: comp,
        sourceHandle: 'infra',
        target: extId,
        targetHandle: 'top',
        className: 'rf-edge-infra',
      })
    }
  })

  return { nodes, edges }
}

